{
  "env": {
    "ANTHROPIC_BASE_URL": "https://skymoni.com",
    "ANTHROPIC_AUTH_TOKEN": "替换成自己的skymoni密钥",
    "ANTHROPIC_MODEL": "替换成完整模型ID"
  }
}

{
  "claudeCode.environmentVariables": [
    { "name": "ANTHROPIC_BASE_URL", "value": "https://skymoni.com" },
    { "name": "ANTHROPIC_AUTH_TOKEN", "value": "替换成自己的skymoni密钥" },
    { "name": "ANTHROPIC_MODEL", "value": "替换成完整模型ID" }
  ]
}

const apiKey = process.env.SKYMONI_API_KEY;
const model = process.env.SKYMONI_MODEL;
if (!apiKey || !model) throw new Error('请先设置密钥和模型环境变量');

const response = await fetch('https://skymoni.com/v1/chat/completions', {
  method: 'POST',
  headers: {
    Authorization: `Bearer ${apiKey}`,
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({
    model,
    messages: [{ role: 'user', content: '请只回复：连接成功' }],
    stream: false,
  }),
  signal: AbortSignal.timeout(120000),
});
if (!response.ok) {
  throw new Error(`HTTP ${response.status}: ${await response.text()}`);
}
const result = await response.json();
console.log(result.choices[0].message.content);
console.log(result.usage);

{
  "$schema": "https://opencode.ai/config.json",
  "model": "skymoni/REPLACE_WITH_MODEL_ID",
  "provider": {
    "skymoni": {
      "npm": "@ai-sdk/openai-compatible",
      "name": "skymoni",
      "options": {
        "baseURL": "https://skymoni.com/v1"
      },
      "models": {
        "REPLACE_WITH_MODEL_ID": {
          "name": "skymoni 编程模型"
        }
      }
    }
  }
}
